program_text:
# A weekly close above the top of a multi-year cup-and-handle in gold is followed by a trend to the measured move more often than a random long of the same holding period.
# Translated from the author's post; the house futures preset (guideline §15).
strategy gold_cup_and_handle {
  data {
    class   future
    need    bars @1d
    need    rolls, listing
    require reviewed
    prefer  latest
  }
  uses  calendar, catalog, stat, bars, book
  clock { decide on base }
  universe {
    universe(A, T) :- listed(A, T), traded@base(A, T), house_list(A).
  }

  params {
    lookback  : Scalar = 250 in 150..350
    stop_atr  : Scalar = 3 in 1..5
    risk      : Notional<USD> = 7_500 USD
    side      : Label = both
  }

  rules {
    rel signal(A: Future, @T)
    signal(A, T) :- universe(A, T), bar(T), setup[lookback](A, T).
    rel stop_hit(A: Future, @T)
    stop_hit(A, T) :- in_book(A, T), atr[20](A, T, R), entry_price(A, P), close(A, T, C), C < P - stop_atr * R.
  }

  decisions {
    silence hold
    orders  market
    decide(T, enter(A, long, risk / R)) :- signal(A, T), atr[20](A, T, R), not in_book(A, T).
    decide(T, exit(A)) :- stop_hit(A, T).
  }

  execution futures_house {
    price         close
    orders        moo_moc
    lot           fractional
    capital       1_000_000 USD fixed
    commission    per_contract 3.75
    slippage      none
    impact        none
    participation none
    financing     none
    leverage      unconstrained
    actions       apply
    delisting     last_price
    oversize      halt
    ruin          halt
    numerics      exact
    settlement    none
  }

  report { metrics [return, volatility, sharpe, mar, max_drawdown, drawdown_duration, trades, profit_factor, hit_rate, avg_win_loss]; tables [surface, subperiods, contribution, trades]; text }
}

