program_text:
# In gold above its 200-day average, a 2-day RSI below 10 at the close is followed by a close above the 5-day average with a profit factor above 1.5 after costs.
# Translated from the author's post; the house futures preset (guideline §15).
strategy gold_rsi2_pullback {
  data {
    class   future
    need    bars @1d
    need    rolls, listing
    require reviewed
    prefer  latest
  }
  uses  calendar, catalog, stat, bars, book
  clock { decide on base }
  universe {
    universe(A, T) :- listed(A, T), traded@base(A, T), house_list(A).
  }

  params {
    rsi_entry  : Scalar = 10 in 5..15
    exit_sma  : Scalar = 5 in 3..10
    risk      : Notional<USD> = 7_500 USD
    side      : Label = both
  }

  rules {
    rel signal(A: Future, @T)
    signal(A, T) :- universe(A, T), bar(T), setup[rsi_entry](A, T).
    rel stop_hit(A: Future, @T)
    stop_hit(A, T) :- in_book(A, T), atr[20](A, T, R), entry_price(A, P), close(A, T, C), C < P - exit_sma * R.
  }

  decisions {
    silence hold
    orders  market
    decide(T, enter(A, long, risk / R)) :- signal(A, T), atr[20](A, T, R), not in_book(A, T).
    decide(T, exit(A)) :- stop_hit(A, T).
  }

  execution futures_house {
    price         close
    orders        moo_moc
    lot           fractional
    capital       1_000_000 USD fixed
    commission    per_contract 3.75
    slippage      none
    impact        none
    participation none
    financing     none
    leverage      unconstrained
    actions       apply
    delisting     last_price
    oversize      halt
    ruin          halt
    numerics      exact
    settlement    none
  }

  report { metrics [return, volatility, sharpe, mar, max_drawdown, drawdown_duration, trades, profit_factor, hit_rate, avg_win_loss]; tables [surface, subperiods, contribution, trades]; text }
}

